def common_elements(a, b):
    """Finds the common elements between two sorted lists."""
    set_a = set(a)
    common = []
    for x in b:
        if x in set_a:
            common.append(x)
    return sorted(common)

def fib(n):
    """Calculates the nth Fibonacci number recursively."""
    if n <= 1:
        return n
    else:
        return fib(n-1) + fib(n-2)

def count_pairs(nums, target):
    """Counts the number of index pairs (i, j) such that nums[i] + nums[j] == target."""
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                count += 1
    return count

def dedupe_keep_order(items):
    """Removes duplicates from a list while preserving the original order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result
